	if r.OK || r.Reason != ReasonPrevLogTermMismatch {
		t.Fatalf("result = %+v", r)
	}
	if r.CommitIndex != 0 || len(out.Log) != 1 {
		t.Fatalf("state changed: commit=%d log=%+v", r.CommitIndex, out.Log)
	}
}

func TestReplicate_TermConflictReplacesSuffix(t *testing.T) {
	// Follower log [1,1,2,2] commit 2; leader sends from index 2 with term 3.
	// Index 3 is uncommitted, so the conflicting entry and its suffix are
	// replaced.
	st := InitialState{CurrentTerm: 2, CommitIndex: 2, Log: logEntries(
		struct {
			term int
			cmd  string
		}{1, "a"},
		struct {
			term int
			cmd  string
		}{1, "b"},
		struct {
			term int
			cmd  string
		}{2, "c"},
		struct {
			term int
			cmd  string
		}{2, "d"},
	)}
	out := run(t, st, ReplicationRequest{
		LeaderTerm: 3, PrevLogIndex: 2, PrevLogTerm: 1,
		Entries: entriesCmd(
			struct {
				term int
				cmd  string
			}{3, "c'"},
			struct {
				term int
				cmd  string
			}{3, "d'"},
		),
		LeaderCommit: 4,
	})
	r := out.Results[0]
	if !r.OK {
		t.Fatalf("result = %+v", r)
	}
	want := []int{1, 1, 3, 3}
	if got := termsOf(out.Log); len(got) != len(want) {
		t.Fatalf("log terms = %v, want %v", got, want)
	} else {
		for i := range want {
			if got[i] != want[i] {
				t.Fatalf("log terms = %v, want %v", got, want)
			}
		}
	}
	if got := cmdsOf(out.Log); got[2] != "c'" || got[3] != "d'" {
		t.Fatalf("log commands = %v", got)
	}
	if r.CommitIndex != 4 {
		t.Fatalf("commit = %d", r.CommitIndex)
	}
}

func TestReplicate_CommittedOverwriteRejected(t *testing.T) {
	// Conflict at index 3 which is already committed: reject atomically.
	st := InitialState{CurrentTerm: 2, CommitIndex: 3, Log: logEntries(
		struct {
			term int
			cmd  string
		}{1, "a"},
		struct {
			term int
			cmd  string
		}{1, "b"},
