		LeaderTerm: 3, PrevLogIndex: 2, PrevLogTerm: 1,
		Entries: entries(3), LeaderCommit: 3,
	})
	r := out.Results[0]
	if r.OK || r.Reason != ReasonCommittedOverwrite {
		t.Fatalf("result = %+v", r)
