func TestReplicate_CommandMismatchRejected(t *testing.T) {
	// Same index and term but different command: reject, no partial append.
	st := InitialState{CurrentTerm: 2, CommitIndex: 1, Log: logEntries(
		struct {
			term int
			cmd  string
		}{1, "a"},
		struct {
			term int
			cmd  string
		}{2, "b"},
	)}
