		LeaderTerm: 2, PrevLogIndex: 1, PrevLogTerm: 1,
		Entries: entriesCmd(
			struct {
				term int
				cmd  string
			}{2, "b"},
			struct {
				term int
				cmd  string
			}{2, "X"},
		),
		LeaderCommit: 3,
	})
	// Position 2: local term 2 == request term 2 but command "b" != "X"?
	// Wait: local[2] is term 2 command "b"; request[0] at index 2 is term 2
	// command "b" -> match. request[1] at index 3 is beyond log -> append.
	// So this would succeed. Use a true mismatch instead.
	if !out.Results[0].OK {
		// The above case is actually valid; keep it as a separate check.
		t.Fatalf("unexpected rejection: %+v", out.Results[0])
	}

	st2 := InitialState{CurrentTerm: 2, CommitIndex: 1, Log: logEntries(
		struct {
			term int
			cmd  string
		}{1, "a"},
		struct {
			term int
			cmd  string
		}{2, "b"},
	)}
	out2 := run(t, st2, ReplicationRequest{
		LeaderTerm: 2, PrevLogIndex: 1, PrevLogTerm: 1,
		Entries: entriesCmd(
			struct {
				term int
				cmd  string
			}{2, "X"},
		),
		LeaderCommit: 2,
	})
	r := out2.Results[0]
	if r.OK || r.Reason != ReasonCommandMismatch {
		t.Fatalf("result = %+v", r)
	}
	if r.CommitIndex != 1 || len(out2.Log) != 2 {
