func TestReplicate_IndexZeroOnlyMatchesTermZero(t *testing.T) {
	st := InitialState{CurrentTerm: 2, CommitIndex: 0, Log: mkLog(entrySpec{1, "a"})}
	out := runReplicate(t, st, ReplicationRequest{
