	if !r.OK {
		t.Fatalf("result = %+v", r)
	}
	if r.CommitIndex != 1 {
		t.Fatalf("commit = %d, want 1 (min(10, prev=1))", r.CommitIndex)
	}
	if len(out.Log) != 3 {
		t.Fatalf("local tail deleted: %+v", out.Log)
	}
}

